import React, { useEffect, useState } from "react";
import ReactDOM from "react-dom/client";
import { App } from "./App";
import { DesktopStartupErrorBoundary } from "./components/DesktopStartupErrorBoundary";
import { CompanionApp } from "./features/companion/CompanionApp";
import { isCompanionWindowSearch } from "./features/companion/companionTypes";
import { deepLinkService } from "./services/deepLinkService";
import { safeModeService } from "./services/safeModeService";
import { crashReporterService } from "./services/crashReporterService";
import { localDataMigrationService } from "./services/localDataMigrationService";
import { productionRuntimeConfigService } from "./services/productionRuntimeConfigService";
import { settingsService } from "./services/settingsService";
import { profileMediaRealtimeService } from "./services/profileMedia/profileMediaRealtimeService";
import { ProductionConfigurationError } from "./components/ProductionConfigurationError";
import "./styles.css";
import "./screenShareQuality.css";

function markRuntime(): void {
  const runtimeInfo = window.picomDesktop?.getRuntimeInfo();

  if (!runtimeInfo) {
    document.documentElement.dataset.runtime = "browser";
  } else {
    document.documentElement.dataset.runtime = runtimeInfo.runtime;
    document.documentElement.dataset.platform = runtimeInfo.platform;
  }

  if (isCompanionWindowSearch()) {
    document.documentElement.dataset.companionWindow = "true";
  }
}

function getRootElement(): HTMLElement {
  const rootElement = document.getElementById("root");

  if (!rootElement) {
    throw new Error("Picom renderer root element was not found.");
  }

  return rootElement;
}

type IdleWindow = Window & typeof globalThis & {
  requestIdleCallback?: (callback: () => void, options?: { timeout: number }) => number;
};

function scheduleOptionalRendererServices(safeModeActive: boolean): void {
  const start = () => {
    if (safeModeActive) return;
    crashReporterService.initialize();
    void profileMediaRealtimeService.start();
    void import("./services/sleepWakeResumeService").then((sleepWakeModule) => {
      sleepWakeModule.sleepWakeResumeService.start();
    }).catch(() => {
      console.warn("Optional renderer services could not start; the desktop shell remains available.");
    });
  };

  const idleWindow = window as IdleWindow;
  if (idleWindow.requestIdleCallback) {
    idleWindow.requestIdleCallback(start, { timeout: 1_200 });
    return;
  }

  window.setTimeout(start, 0);
}

/** Switches between main desktop App and Electron Companion windows (`?picomWindow=companion`). */
function DesktopRendererRoot() {
  const [companionWindow, setCompanionWindow] = useState(() => isCompanionWindowSearch());

  useEffect(() => {
    const sync = () => {
      const next = isCompanionWindowSearch();
      setCompanionWindow(next);
      if (next) document.documentElement.dataset.companionWindow = "true";
      else delete document.documentElement.dataset.companionWindow;
    };
    window.addEventListener("popstate", sync);
    return () => window.removeEventListener("popstate", sync);
  }, []);

  return companionWindow ? <CompanionApp /> : <App />;
}

function bootstrapRenderer(): void {
  markRuntime();
  const productionConfiguration = productionRuntimeConfigService.getConfiguration();
  if (!productionConfiguration.ready) {
    ReactDOM.createRoot(getRootElement()).render(
      <React.StrictMode>
        <DesktopStartupErrorBoundary>
          <ProductionConfigurationError configuration={productionConfiguration} />
        </DesktopStartupErrorBoundary>
      </React.StrictMode>,
    );
    return;
  }
  const migration = localDataMigrationService.migrateOnStartup();
  if (!migration.ok) safeModeService.enableSafeMode("local_data_migration_failed");
  // Warm settings so corrupted local JSON can flip Safe Mode before optional services start.
  settingsService.getSettings();
  const safeMode = safeModeService.getStartupState();
  const companionWindow = isCompanionWindowSearch();

  // Companion windows are dedicated shells; deep links belong on the main window.
  if (!safeMode.active && !companionWindow) {
    deepLinkService.startNativeListener();
  }

  ReactDOM.createRoot(getRootElement()).render(
    <React.StrictMode>
      <DesktopStartupErrorBoundary>
        <DesktopRendererRoot />
      </DesktopStartupErrorBoundary>
    </React.StrictMode>
  );

  scheduleOptionalRendererServices(safeMode.active);
}

bootstrapRenderer();

export type CompanionWindowType =
  | "home"
  | "chat"
  | "voice"
  | "video"
  | "community"
  | "dock"
  | "bubble"
  | "settings"
  | "notification"
  | "gaming";

export type CompanionDockEdge = "left" | "right" | "top" | "bottom";

export type CompanionStartupMode = "main" | "companion";
export type CompanionDockLayout = "collapsed" | "rail" | "expanded";

export type CompanionRoute = Readonly<{
  type: CompanionWindowType;
  conversationId?: string;
  callId?: string;
  communityId?: string;
  channelId?: string;
}>;

export type CompanionPreferences = Readonly<{
  version: 1;
  startupMode: CompanionStartupMode;
  alwaysOnTop: boolean;
  compactDensity: boolean;
  closeToTray: boolean;
  showNotifications: boolean;
  theme: "system" | "light" | "dark";
  windowOpacity: number;
  dockEdge: CompanionDockEdge;
  smartCollapse: boolean;
  dockAutoHide: boolean;
  gamingAutoDetect: boolean;
}>;

export type CompanionPerson = Readonly<{
  userId: string;
  displayName: string;
  username: string;
  avatarUrl?: string;
  status: "online" | "idle" | "busy" | "offline";
  favorite: boolean;
  conversationId?: string;
  unreadCount?: number;
  activityLabel?: string;
  lastMessagePreview?: string;
}>;

export type CompanionCommunity = Readonly<{
  id: string;
  name: string;
  description?: string;
  iconUrl?: string;
}>;

export type CompanionVoiceRoom = Readonly<{
  id: string;
  communityId: string;
  name: string;
  communityName: string;
  participantCount: number;
}>;

export type CompanionHomeSnapshot = Readonly<{
  currentUser: Readonly<{ userId: string; displayName: string; username: string }> | null;
  people: readonly CompanionPerson[];
  communities: readonly CompanionCommunity[];
  conversations: readonly unknown[];
  voiceRooms: readonly CompanionVoiceRoom[];
  totalUnread: number;
  updatedAt: string;
}>;

const WINDOW_TYPES = new Set<CompanionWindowType>([
  "home", "chat", "voice", "video", "community", "dock", "bubble", "settings", "notification", "gaming",
]);

function resolveWindowType(value: string | null): CompanionWindowType {
  if (value && WINDOW_TYPES.has(value as CompanionWindowType)) return value as CompanionWindowType;
  return "home";
}

export function isCompanionWindowSearch(search = typeof window !== "undefined" ? window.location.search : ""): boolean {
  return new URLSearchParams(search).get("picomWindow") === "companion";
}

export function parseCompanionRoute(search = window.location.search): CompanionRoute {
  const params = new URLSearchParams(search);
  const type = resolveWindowType(params.get("type") ?? params.get("surface"));
  const optional = (name: string) => params.get(name) || undefined;
  return Object.freeze({
    type,
    conversationId: optional("conversationId"),
    callId: optional("callId"),
    communityId: optional("communityId"),
    channelId: optional("channelId"),
  });
}

export function companionStatusLabel(status: CompanionPerson["status"]): string {
  switch (status) {
    case "online": return "Çevrimiçi";
    case "idle": return "Boşta";
    case "busy": return "Rahatsız Etmeyin";
    default: return "Çevrimdışı";
  }
}

/**
 * Ensures desktop renderer entry wires CompanionApp for Electron companion windows.
 */
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import test from "node:test";

const ROOT = process.cwd();
const MAIN = join(ROOT, "src/main.tsx");
const TYPES = join(ROOT, "src/features/companion/companionTypes.ts");
const APP = join(ROOT, "src/features/companion/CompanionApp.tsx");

test("companionTypes exports isCompanionWindowSearch", () => {
  const src = readFileSync(TYPES, "utf8");
  assert.match(src, /export function isCompanionWindowSearch/);
  assert.match(src, /\.get\(\s*["']picomWindow["']\s*\)\s*===\s*["']companion["']/);
});

test("main.tsx imports and mounts CompanionApp for companion windows", () => {
  const src = readFileSync(MAIN, "utf8");
  assert.match(src, /from ["']\.\/features\/companion\/CompanionApp["']/);
  assert.match(src, /from ["']\.\/features\/companion\/companionTypes["']/);
  assert.match(src, /isCompanionWindowSearch/);
  assert.match(src, /<CompanionApp\s*\/>/);
  assert.match(src, /function DesktopRendererRoot/);
  assert.match(src, /<DesktopRendererRoot\s*\/>/);
  assert.match(src, /companionWindow\s*\?\s*<CompanionApp/);
});

test("CompanionApp remains the companion shell export", () => {
  const src = readFileSync(APP, "utf8");
  assert.match(src, /export function CompanionApp\s*\(/);
  assert.match(src, /parseCompanionRoute/);
});

test("electron companion windows load picomWindow=companion query", () => {
  const src = readFileSync(join(ROOT, "electron/companionWindowManager.cts"), "utf8");
  assert.match(src, /picomWindow:\s*["']companion["']/);
  assert.match(src, /searchParams\.set/);
});
